struct Chunk { id: u32, state: ChunkState,
} #[derive(Resource)]
struct Chunks(HashMap<u32, Chunk>); 然后我们可以创建一个插件，在我们的主应用程序上创建并插入一个子应用程序。这个子应用程序将在我们的主应用程序之后连续运行，而不是并行运行。 #[derive(Debug, Clone, Copy, Hash, PartialEq, Eq, AppLabel)]
pub struct ChunkApp; fn update_chunks(mut chunks: ResMut<Chunks>) { for chunk in chunks.0.values_mut() { match chunk.state { ChunkState::Red => chunk.state = ChunkState::Green, ChunkState::Green => chunk.state = ChunkState::Blue, ChunkState::Blue => chunk.state = ChunkState::Red, } }
} struct ChunksPlugin; impl Plugin for ChunksPlugin { fn build(&self, app: &mut App) { let mut sub_app = SubApp::new(); // Set up our sub app sub_app .insert_resource(Chunk::default()) .add_systems(Update, update_chunks); // Set up how we will extract data from our main world -> sub world sub_app.set_extract(|main_world, sub_world| { let mut chunks = main_world.resource_mut::<Chunks>(); let chunk = sub_world.resource::<Chunk>(); chunks.0.insert(chunk.id, chunk.clone()); }); // Add our sub app to our main app app.insert_sub_app(ChunkApp, sub_app); }
} 有关更多性能问题的更完整示例，您可以查看bevy/crates/bevy_render中使用async的pipelined_rendering.rs。

